const crypto = require("crypto");
// Test verifyState behavior with mismatched lengths
function verifyState(session, supplied) {
  return crypto.timingSafeEqual(Buffer.from(session.oauthState), Buffer.from(supplied));
}
// normal state is 32 bytes hex = 64 chars
const session = { oauthState: crypto.randomBytes(32).toString("hex") };
// attacker supplies different length
try {
  verifyState(session, "abc");
  console.log("short supplied: returned (no throw)");
} catch (e) {
  console.log("short supplied THROWS:", e.constructor.name, "-", e.message);
}
try {
  verifyState(session, session.oauthState + "extra");
  console.log("long supplied: returned (no throw)");
} catch (e) {
  console.log("long supplied THROWS:", e.constructor.name, "-", e.message);
}
try {
  verifyState(session, undefined);
  console.log("undefined supplied: returned (no throw)");
} catch (e) {
  console.log("undefined supplied THROWS:", e.constructor.name, "-", e.message);
}
// Correct (equal length, wrong value) - should return false, not throw
console.log("equal-length wrong value returns:", verifyState(session, "a".repeat(64)));
console.log("equal-length correct value returns:", verifyState(session, session.oauthState));

// Buffer.from(undefined) behavior
try { console.log("Buffer.from(undefined):", Buffer.from(undefined)); }
catch(e){ console.log("Buffer.from(undefined) THROWS:", e.message); }
'
"}

