// Verify the exactRedirect combined with the prefix redirect validation trust boundary
// register.js validateRedirect uses startsWith(client.baseUrl)
// exact-redirect.js exactRedirect compares protocol/host/port/pathname only (NO query/fragment)
// So if a redirect handler uses exactRedirect as the only check against an attacker-supplied redirect_uri,
// an attacker can append arbitrary query string to a registered redirect.

// Also confirm: exactRedirect does NOT compare query or fragment
const { exactRedirect } = require("./src/oauth/exact-redirect");
