const registered = "https://portal.example.test/callback";
const supplied = "https://portal.example.test/callback?redirect_uri=https://evil.com";
console.log("passes exactRedirect (query injected):", exactRedirect(registered, supplied));

// What about username/password bypass in exactRedirect? It compares hostname not host string
// registered https://portal.example.test/cb vs supplied https://portal.example.test:443/cb? 
console.log("default port 443 vs no port:", exactRedirect("https://portal.example.test/cb","https://portal.example.test:443/cb"));
'
"}

